// A constructor that forwards into a caller contract another module of the
// package defines (`area.ts`); `caller_contract_forward_import`'s `main.ts`.
import { area } from "./area"

export class Grid {
  width: i32
  height: i32
  cells: i32

  constructor(width: i32, height: i32) {
    const cells: i32 = area("Grid", width, height)
    this.width = width
    this.height = height
    this.cells = cells
  }
}
